  "sv.ag_title": { pt: "Agentes no terreno", en: "Field agents", zh: "地推代理", fr: "Agents de terrain" },
  "sv.ag_intro": { pt: "Trabalha numa praça (por exemplo, o Kapango) ou conhece pessoas sem telemóvel ou que não sabem usar a internet? Ajude-as a pôr anúncios de venda, troca ou leilão no Huambo Online e ganhe uma comissão sempre que um desses anúncios for vendido.", en: "Do you work at a market (for example, Kapango) or know people without a phone or who don't know how to use the internet? Help them post sale, trade or auction listings on Huambo Online and earn a commission every time one of those listings is sold.", zh: "您在市场（例如 Kapango）工作，或认识没有手机、不会上网的人吗？帮助他们在 Huambo Online 发布出售、交换或拍卖广告，每当其中一条广告成交，您就能获得佣金。", fr: "Vous travaillez dans un marché (par exemple, Kapango) ou connaissez des personnes sans téléphone ou qui ne savent pas utiliser internet ? Aidez-les à publier des annonces de vente, d'échange ou d'enchère sur Huambo Online et touchez une commission chaque fois qu'une de ces annonces est vendue." },
  "sv.ag_step1": { pt: "Peça para ser agente (escolha a sua praça). A administração confirma.", en: "Apply to be an agent (choose your market). The administration confirms.", zh: "申请成为代理（选择您的市场），由管理员确认。", fr: "Postulez pour devenir agent (choisissez votre marché). L'administration confirme." },
  "sv.ag_step2": { pt: "Recebe um código, por exemplo", en: "You get a code, for example", zh: "您会获得一个代码，例如", fr: "Vous recevez un code, par exemple" },
  "sv.ag_step3": { pt: "Ajude o vendedor a publicar na conta dele e peça-lhe para escrever o seu código.", en: "Help the seller post from their own account and ask them to enter your code.", zh: "帮助卖家用其本人账户发布，并请他填写您的代码。", fr: "Aidez le vendeur à publier depuis son propre compte et demandez-lui d'indiquer votre code." },
  "sv.ag_step4": { pt: "Quando o vendedor marcar o anúncio como vendido, ganha a sua parte do valor da venda.", en: "When the seller marks the listing as sold, you earn your share of the sale amount.", zh: "卖家将广告标记为已售出后，您即可获得销售额中您的那一份。", fr: "Quand le vendeur marque l'annonce comme vendue, vous gagnez votre part du montant de la vente." },
  "sv.ag_step5": { pt: "Depois de a administração confirmar, o valor entra no seu", en: "Once the administration confirms, the amount goes into your", zh: "管理员确认后，金额会进入您的", fr: "Une fois confirmé par l'administration, le montant va dans votre" },
  "sv.ag_step5_b": { pt: "e pode levantar.", en: "and you can withdraw it.", zh: "，随后即可提现。", fr: "et vous pouvez le retirer." },
