  "sv.ag_note_ph": { pt: "Ex.: vendo na banca 12 e conheço muitos vendedores.", en: "E.g.: I sell at stall 12 and know many sellers.", zh: "例如：我在 12 号摊位卖货，认识很多卖家。", fr: "Ex. : je vends à l'étal 12 et je connais beaucoup de vendeurs." },
  "sv.ag_pending": { pt: "Estamos a ver o seu pedido. Recebe um aviso quando for aprovado.", en: "We are reviewing your request. You'll get a notice when it's approved.", zh: "我们正在审核您的申请，批准后会通知您。", fr: "Nous examinons votre demande. Vous recevrez un avis quand elle sera approuvée." },
  "sv.ag_rejected": { pt: "Pode corrigir os dados e pedir outra vez.", en: "You can correct your details and apply again.", zh: "您可以修改资料后重新申请。", fr: "Vous pouvez corriger vos données et postuler à nouveau." },
