  "sv.ag_code_shape": { pt: "O código começa por AG e tem números (ex.: AG1001).", en: "The code starts with AG followed by numbers (e.g.: AG1001).", zh: "代码以 AG 开头，后跟数字（例如：AG1001）。", fr: "Le code commence par AG suivi de chiffres (ex. : AG1001)." },
  "sv.ag_code_help": { pt: "Se um agente do Huambo Online o ajudou a pôr este anúncio, escreva o código dele.", en: "If a Huambo Online agent helped you post this listing, enter their code.", zh: "如果有 Huambo Online 代理协助您发布此广告，请填写其代码。", fr: "Si un agent de Huambo Online vous a aidé à publier cette annonce, indiquez son code." },
