  "sv.ag_rules_saved": { pt: "Regras dos agentes guardadas.", en: "Agent rules saved.", zh: "代理规则已保存。", fr: "Règles des agents enregistrées." },
  "sv.ag_pct": { pt: "Percentagem do agente em cada venda (%)", en: "Agent percentage on each sale (%)", zh: "代理每笔销售的佣金比例（%）", fr: "Pourcentage de l'agent sur chaque vente (%)" },
  "sv.ag_pct_hint": { pt: "Quando um anúncio feito com o código do agente é vendido, o agente ganha esta percentagem do valor da venda. Antes de confirmar, veja se o vendedor já pagou a comissão da venda.", en: "When a listing posted with the agent's code is sold, the agent earns this percentage of the sale amount. Before confirming, check that the seller has paid the sale commission.", zh: "使用代理代码发布的广告成交后，代理按此比例获得销售额佣金。确认前，请检查卖家是否已支付销售佣金。", fr: "Quand une annonce publiée avec le code de l'agent est vendue, l'agent gagne ce pourcentage du montant de la vente. Avant de confirmer, vérifiez que le vendeur a payé la commission de vente." },
