  "sv.vf_bi_bad": { pt: "Ainda não está certo: 9 algarismos, 2 letras e 3 algarismos.", en: "Not right yet: 9 digits, 2 letters and 3 digits.", zh: "格式还不正确：9 位数字、2 个字母和 3 位数字。", fr: "Pas encore correct : 9 chiffres, 2 lettres et 3 chiffres." },
