  "sv.vf_intro_a": { pt: "A administração confirma quem é. Depois de aprovado, o seu perfil mostra o selo", en: "The administration confirms who you are. Once approved, your profile shows the badge", zh: "管理员会确认您的身份。通过后，您的资料将显示", fr: "L'administration confirme qui vous êtes. Une fois approuvé, votre profil affiche le badge" },
  "sv.vf_intro_b": { pt: "e os clientes confiam mais.", en: "and clients trust you more.", zh: "标志，客户会更加信任您。", fr: "et les clients vous font davantage confiance." },
  "sv.vf_private": { pt: "As fotografias e os documentos ficam guardados numa pasta privada: só a administração os pode ver. Nunca são mostrados no site nem a outras pessoas.", en: "Photos and documents are kept in a private folder: only the administration can see them. They are never shown on the site or to other people.", zh: "照片和文件保存在私密文件夹中，只有管理员可以查看，绝不会在网站上展示或给其他人看。", fr: "Les photos et documents sont conservés dans un dossier privé : seule l'administration peut les voir. Ils ne sont jamais affichés sur le site ni montrés à d'autres personnes." },
  "sv.vf_what": { pt: "O que quer verificar?", en: "What do you want to verify?", zh: "您要验证什么？", fr: "Que voulez-vous vérifier ?" },
  "sv.vf_id_ok": { pt: "A sua identidade já está verificada.", en: "Your identity is already verified.", zh: "您的身份已验证。", fr: "Votre identité est déjà vérifiée." },
  "sv.vf_id_pending": { pt: "O seu pedido de verificação da identidade está à espera de análise. Recebe uma notificação com a resposta.", en: "Your identity verification request is awaiting review. You'll get a notification with the answer.", zh: "您的身份验证申请正在等待审核，您会收到结果通知。", fr: "Votre demande de vérification d'identité est en attente d'examen. Vous recevrez une notification avec la réponse." },
