  "sv.vf_admin_note": { pt: "Nota da administração", en: "Administration note", zh: "管理员备注", fr: "Note de l'administration" },
  "sv.wait": { pt: "Aguarde…", en: "Please wait…", zh: "请稍候…", fr: "Veuillez patienter…" },
  "sv.mfa_on_done": { pt: "Pronto! A entrada em dois passos está ligada. Da próxima vez que entrar, vamos pedir o código da APP autenticadora.", en: "Done! Two-step sign-in is on. Next time you sign in, we'll ask for the code from the authenticator app.", zh: "完成！两步登录已开启。下次登录时，我们会要求输入身份验证器应用中的代码。", fr: "C'est fait ! La connexion en deux étapes est activée. À votre prochaine connexion, nous vous demanderons le code de l'application d'authentification." },
  "sv.mfa_copy_fail": { pt: "Não foi possível copiar. Escreva a chave à mão.", en: "Couldn't copy. Type the key by hand.", zh: "无法复制，请手动输入密钥。", fr: "Impossible de copier. Saisissez la clé à la main." },
  "sv.mfa_off_q": { pt: "Desligar a entrada em dois passos? A sua conta fica menos protegida: basta a palavra-passe para entrar.", en: "Turn off two-step sign-in? Your account will be less protected: the password alone will be enough to sign in.", zh: "关闭两步登录？您的账户安全性会降低：仅凭密码即可登录。", fr: "Désactiver la connexion en deux étapes ? Votre compte sera moins protégé : le mot de passe seul suffira pour se connecter." },
  "sv.mfa_off_done": { pt: "A entrada em dois passos foi desligada.", en: "Two-step sign-in has been turned off.", zh: "两步登录已关闭。", fr: "La connexion en deux étapes a été désactivée." },
  "sv.mfa_title": { pt: "Entrar em dois passos", en: "Two-step sign-in", zh: "两步登录", fr: "Connexion en deux étapes" },
  "sv.mfa_intro": { pt: "Proteja a sua conta: além da palavra-passe, para entrar é preciso um código de 6 algarismos que muda a cada 30 segundos, mostrado por uma APP no seu telemóvel. Mesmo que alguém descubra a palavra-passe, não consegue entrar sem o seu telemóvel.", en: "Protect your account: besides the password, signing in requires a 6-digit code that changes every 30 seconds, shown by an app on your phone. Even if someone finds out your password, they can't sign in without your phone.", zh: "保护您的账户：除密码外，登录还需要手机应用显示的 6 位验证码，每 30 秒更新一次。即使有人知道您的密码，没有您的手机也无法登录。", fr: "Protégez votre compte : en plus du mot de passe, la connexion exige un code à 6 chiffres qui change toutes les 30 secondes, affiché par une application sur votre téléphone. Même si quelqu'un découvre votre mot de passe, il ne peut pas se connecter sans votre téléphone." },
  "sv.mfa_on": { pt: "Ligado", en: "On", zh: "已开启", fr: "Activée" },
  "sv.mfa_on_text": { pt: "A entrada em dois passos está ligada.", en: "Two-step sign-in is on.", zh: "两步登录已开启。", fr: "La connexion en deux étapes est activée." },
  "sv.mfa_on_since": { pt: "A entrada em dois passos está ligada desde {date}.", en: "Two-step sign-in has been on since {date}.", zh: "两步登录自 {date} 起已开启。", fr: "La connexion en deux étapes est activée depuis le {date}." },
  "sv.mfa_on_hint": { pt: "Ao entrar, vamos pedir o código da APP autenticadora.", en: "When you sign in, we'll ask for the code from the authenticator app.", zh: "登录时，我们会要求输入身份验证器应用中的代码。", fr: "Lors de la connexion, nous vous demanderons le code de l'application d'authentification." },
  "sv.mfa_confirm_off": { pt: "Confirme com o código para desligar", en: "Confirm with the code to turn it off", zh: "请输入验证码确认关闭", fr: "Confirmez avec le code pour la désactiver" },
  "sv.mfa_turn_off": { pt: "Desligar", en: "Turn off", zh: "关闭", fr: "Désactiver" },
  "sv.mfa_turn_on": { pt: "Ligar", en: "Turn on", zh: "开启", fr: "Activer" },
