  "sv.mfa_qr_alt": { pt: "Código QR para ler com a APP autenticadora", en: "QR code to scan with the authenticator app", zh: "用身份验证器应用扫描的二维码", fr: "Code QR à scanner avec l'application d'authentification" },
  "sv.mfa_no_qr": { pt: "Não consegue ler o código QR? Na APP escolha «Introduzir chave» e escreva esta chave:", en: "Can't scan the QR code? In the app choose “Enter key” and type this key:", zh: "无法扫描二维码？请在应用中选择“输入密钥”，并输入以下密钥：", fr: "Vous ne pouvez pas scanner le code QR ? Dans l'application, choisissez « Saisir une clé » et tapez cette clé :" },
  "sv.mfa_key_aria": { pt: "Chave para escrever na APP", en: "Key to type in the app", zh: "在应用中输入的密钥", fr: "Clé à saisir dans l'application" },
  "sv.mfa_copied": { pt: "Copiada", en: "Copied", zh: "已复制", fr: "Copié" },
  "sv.mfa_copy": { pt: "Copiar a chave", en: "Copy the key", zh: "复制密钥", fr: "Copier la clé" },
