  "sv.mfa_how": { pt: "Como ligar:", en: "How to turn it on:", zh: "开启方法：", fr: "Comment l'activer :" },
  "sv.mfa_lose_warn": { pt: "Se perder o telemóvel ou apagar a APP, deixa de conseguir entrar sozinho: terá de falar com a administração.", en: "If you lose your phone or delete the app, you won't be able to sign in on your own: you'll have to contact the administration.", zh: "如果您丢失手机或删除应用，将无法自行登录，需要联系管理员。", fr: "Si vous perdez votre téléphone ou supprimez l'application, vous ne pourrez plus vous connecter seul : il faudra contacter l'administration." },
  "sv.mfa_login_b": { pt: "para proteger a sua conta.", en: "to protect your account.", zh: "以保护您的账户。", fr: "pour protéger votre compte." },
  "sv.mfa_gate_intro": { pt: "Esta conta tem a entrada em dois passos ligada. Para mudar estas definições, escreva primeiro o código da APP autenticadora.", en: "This account has two-step sign-in turned on. To change these settings, first type the code from the authenticator app.", zh: "此账户已开启两步登录。要更改这些设置，请先输入身份验证器应用中的代码。", fr: "Ce compte a la connexion en deux étapes activée. Pour modifier ces paramètres, saisissez d'abord le code de l'application d'authentification." },
