  "sv.fu_proof_required": { pt: "Fotografia ou PDF do comprovativo (obrigatório)", en: "Photo or PDF of the receipt (required)", zh: "付款凭证照片或 PDF（必填）", fr: "Photo ou PDF du justificatif (obligatoire)" },
  "sv.fu_paid_send": { pt: "Já paguei — enviar comprovativo", en: "I've paid — send receipt", zh: "我已付款——提交凭证", fr: "J'ai payé — envoyer le justificatif" },
  "sv.fu_cancel_btn": { pt: "Cancelar reserva", en: "Cancel reservation", zh: "取消预订", fr: "Annuler la réservation" },
  "sv.fu_have_station_intro": { pt: "Registe o seu posto de combustível ou ponto de venda de gás e marque quando há. É grátis.", en: "Register your fuel station or gas outlet and mark when you have stock. It's free.", zh: "登记您的加油站或燃气销售点，并标记有货状态。完全免费。", fr: "Inscrivez votre station de carburant ou votre point de vente de gaz et indiquez quand vous avez du stock. C'est gratuit." },
  "sv.fu_my_stations": { pt: "Os meus postos", en: "My stations", zh: "我的加油站", fr: "Mes stations" },
  "sv.fu_register": { pt: "Registar posto", en: "Register station", zh: "登记加油站", fr: "Inscrire une station" },
  "sv.fu_my_stations_intro": { pt: "Registar e marcar quando há é grátis. Nas reservas, o cliente paga ao posto o combustível mais a taxa do APP; o posto entrega essa taxa ao Huambo Online.", en: "Registering and marking availability is free. With reservations, the client pays the station for the fuel plus the APP fee; the station passes that fee on to Huambo Online.", zh: "登记和标记有货均免费。预订时，客户向加油站支付燃油费和 APP 服务费，加油站再将该服务费交给 Huambo Online。", fr: "L'inscription et l'indication de disponibilité sont gratuites. Avec les réservations, le client paie à la station le carburant plus les frais de l'APP ; la station reverse ces frais à Huambo Online." },
  "sv.fu_none_registered": { pt: "Ainda não registou nenhum posto.", en: "You haven't registered any station yet.", zh: "您还没有登记任何加油站。", fr: "Vous n'avez encore inscrit aucune station." },
  "sv.fu_approved": { pt: "Aprovado", en: "Approved", zh: "已批准", fr: "Approuvé" },
  "sv.fu_pending": { pt: "À espera de aprovação", en: "Awaiting approval", zh: "等待批准", fr: "En attente d'approbation" },
  "sv.fu_edit": { pt: "Editar posto", en: "Edit station", zh: "编辑加油站", fr: "Modifier la station" },
  "sv.fu_edit_warn": { pt: "Se mudar o nome, o local ou a conta para pagamentos, o posto volta a ficar à espera de aprovação da administração (para evitar burlas).", en: "If you change the name, location or payment account, the station goes back to awaiting administration approval (to prevent scams).", zh: "如果您更改名称、地点或收款账户，加油站将重新等待管理员批准（以防诈骗）。", fr: "Si vous changez le nom, l'emplacement ou le compte de paiement, la station repasse en attente d'approbation par l'administration (pour éviter les arnaques)." },
  "sv.fu_register_note": { pt: "A administração confirma o posto antes de aparecer ao público (para evitar postos falsos).", en: "The administration confirms the station before it appears to the public (to prevent fake stations).", zh: "加油站经管理员确认后才会对公众显示（以防虚假加油站）。", fr: "L'administration confirme la station avant qu'elle n'apparaisse au public (pour éviter les fausses stations)." },
  "sv.fu_name_ph": { pt: "Ex.: Posto Sonangol do Kapango", en: "E.g.: Sonangol Kapango station", zh: "例如：Kapango 的 Sonangol 加油站", fr: "Ex. : Station Sonangol du Kapango" },
