  "sv.fu_place_hint": { pt: "Marque a entrada do posto para as pessoas chegarem sem se perderem.", en: "Mark the station entrance so people can get there without getting lost.", zh: "请标出加油站入口，方便大家顺利找到。", fr: "Indiquez l'entrée de la station pour que les gens arrivent sans se perdre." },
