  "sv.fu_accept_res": { pt: "Aceito reservas (o cliente paga no posto)", en: "I accept reservations (the client pays at the station)", zh: "接受预订（客户在加油站付款）", fr: "J'accepte les réservations (le client paie à la station)" },
  "sv.fu_accept_prepay": { pt: "Aceito pagamento adiantado (Multicaixa Express ou transferência)", en: "I accept advance payment (Multicaixa Express or transfer)", zh: "接受预付款（Multicaixa Express 或转账）", fr: "J'accepte le paiement anticipé (Multicaixa Express ou virement)" },
