  "sv.fu_pay_confirmed_code": { pt: "Pagamento confirmado: o cliente recebeu o código.", en: "Payment confirmed: the client has received the code.", zh: "付款已确认：客户已收到代码。", fr: "Paiement confirmé : le client a reçu le code." },
  "sv.fu_cancelled_refund": { pt: "Reserva cancelada. Se o cliente já pagou, devolva o dinheiro.", en: "Reservation cancelled. If the client has already paid, refund the money.", zh: "预订已取消。如客户已付款，请退还款项。", fr: "Réservation annulée. Si le client a déjà payé, remboursez-le." },
  "sv.fu_has_or_not": { pt: "Há ou não há?", en: "Available or not?", zh: "有没有货？", fr: "Disponible ou non ?" },
  "sv.fu_has_or_not_hint": { pt: "Carregue num botão sempre que mudar. Quem pediu aviso recebe logo uma notificação quando marcar «Há».", en: "Tap a button whenever it changes. People who asked for an alert get a notification as soon as you mark “Available”.", zh: "状态变化时请点击按钮。您标记“有货”后，设置了提醒的用户会立即收到通知。", fr: "Touchez un bouton à chaque changement. Les personnes qui ont demandé une alerte reçoivent une notification dès que vous marquez « Disponible »." },
  "sv.fu_client_qr": { pt: "Cliente com QR ou código", en: "Client with QR or code", zh: "持二维码或代码的客户", fr: "Client avec QR ou code" },
  "sv.fu_client_qr_hint": { pt: "Leia o QR do cliente com a câmara do telemóvel: abre a página que confirma se é verdadeiro e mostra o comprovativo. Ou escreva o código.", en: "Scan the client's QR with your phone camera: it opens the page that confirms whether it's genuine and shows the receipt. Or type the code.", zh: "用手机相机扫描客户的二维码：会打开确认真伪并显示付款凭证的页面。也可以输入代码。", fr: "Scannez le QR du client avec la caméra du téléphone : cela ouvre la page qui confirme s'il est authentique et affiche le justificatif. Ou tapez le code." },
