  "sv.fu_pay_to_confirm": { pt: "Pagamentos por confirmar ({n})", en: "Payments to confirm ({n})", zh: "待确认付款（{n}）", fr: "Paiements à confirmer ({n})" },
  "sv.fu_check_bank": { pt: "Veja na sua conta bancária se entrou {total} com o descritivo {ref}. Inclui {fee} de taxa do APP.", en: "Check in your bank account whether {total} came in with the description {ref}. It includes {fee} APP fee.", zh: "请在您的银行账户中查看是否收到备注为 {ref} 的 {total}。其中包含 APP 服务费 {fee}。", fr: "Vérifiez sur votre compte bancaire si {total} est arrivé avec le descriptif {ref}. Cela inclut {fee} de frais APP." },
  "sv.fu_active": { pt: "Reservas ativas ({n})", en: "Active reservations ({n})", zh: "有效预订（{n}）", fr: "Réservations actives ({n})" },
