  "sv.fu_fee_explain": { pt: "Os clientes pagam ao posto o combustível mais a taxa do APP. Depois de levantarem, o posto entrega a taxa ao Huambo Online.", en: "Clients pay the station for the fuel plus the APP fee. After they collect, the station passes the fee on to Huambo Online.", zh: "客户向加油站支付燃油费和 APP 服务费。领取后，加油站将服务费交给 Huambo Online。", fr: "Les clients paient à la station le carburant plus les frais de l'APP. Après le retrait, la station reverse les frais à Huambo Online." },
  "sv.fu_fee_overdue": { pt: "Taxa do APP em atraso: as reservas estão paradas até entregar.", en: "APP fee overdue: reservations are paused until you pay it.", zh: "APP 服务费逾期：在缴纳之前暂停预订。", fr: "Frais APP en retard : les réservations sont en pause jusqu'au paiement." },
  "sv.fu_pay_fee": { pt: "Entregar a taxa do APP", en: "Pay the APP fee", zh: "缴纳 APP 服务费", fr: "Payer les frais APP" },
  "sv.fu_pay_fee_hint": { pt: "Pague até 7 dias depois do levantamento. Marcar «Há» e registar o posto é sempre grátis.", en: "Pay within 7 days of collection. Marking “Available” and registering the station is always free.", zh: "请在领取后 7 天内缴纳。标记“有货”和登记加油站始终免费。", fr: "Payez dans les 7 jours suivant le retrait. Marquer « Disponible » et inscrire la station est toujours gratuit." },
  "sv.fu_fee_sent": { pt: "Pagamento da taxa enviado. A administração vai confirmar.", en: "Fee payment sent. The administration will confirm it.", zh: "服务费付款已提交，管理员将进行确认。", fr: "Paiement des frais envoyé. L'administration va le confirmer." },
  "sv.fu_station_approved": { pt: "Posto aprovado: já aparece ao público.", en: "Station approved: it now appears to the public.", zh: "加油站已批准：现已对公众显示。", fr: "Station approuvée : elle apparaît maintenant au public." },
  "sv.fu_check_pct": { pt: "Verifique a percentagem e os minutos.", en: "Check the percentage and the minutes.", zh: "请检查百分比和分钟数。", fr: "Vérifiez le pourcentage et les minutes." },
