  "sv.fu_other_role": { pt: "Este pedido existe no Huambo Online. Só o posto {name}, com a sua conta, vê os dados e pode entregar.", en: "This order exists on Huambo Online. Only the station {name}, signed in to its account, can see the details and deliver.", zh: "此订单在 Huambo Online 上真实存在。只有登录账户的 {name} 加油站才能查看详情并交付。", fr: "Cette commande existe sur Huambo Online. Seule la station {name}, connectée à son compte, peut voir les détails et livrer." },
