  "sv.sf_intro": { pt: "A maior parte das pessoas é honesta. Estas regras simples protegem-no das poucas que não são.", en: "Most people are honest. These simple rules protect you from the few who aren't.", zh: "大多数人都是诚实的。这些简单的规则能保护您免受少数不诚实者的侵害。", fr: "La plupart des gens sont honnêtes. Ces règles simples vous protègent des rares qui ne le sont pas." },
  "sv.sf_rules": { pt: "Regras de ouro", en: "Golden rules", zh: "黄金法则", fr: "Règles d'or" },
  "sv.sf_spots": { pt: "Pontos de encontro seguros", en: "Safe meeting points", zh: "安全见面地点", fr: "Points de rencontre sûrs" },
  "sv.sf_spots_intro": { pt: "Para ver o artigo e pagar, combine num destes lugares:", en: "To see the item and pay, arrange to meet in one of these places:", zh: "查看物品和付款时，请约在以下地点之一：", fr: "Pour voir l'article et payer, donnez rendez-vous dans l'un de ces lieux :" },
  "sv.sf_scam": { pt: "Sinais de burla", en: "Scam warning signs", zh: "诈骗迹象", fr: "Signes d'arnaque" },
  "sv.sf_scam_intro": { pt: "Nas mensagens, o Huambo Online avisa-o quando a outra pessoa:", en: "In messages, Huambo Online warns you when the other person:", zh: "在消息中，如果对方出现以下情况，Huambo Online 会提醒您：", fr: "Dans les messages, Huambo Online vous avertit quand l'autre personne :" },
  "sv.sf_block": { pt: "Bloquear e 🚩 Denunciar", en: "Block and 🚩 Report", zh: "屏蔽和 🚩 举报", fr: "Bloquer et 🚩 Signaler" },
  "sv.sf_block_text": { pt: "Numa conversa, carregue em «🚫 Bloquear» para deixar de receber mensagens dessa pessoa e em «🚩 Denunciar» para avisar a administração. Na Loja, use o Pagamento protegido quando estiver disponível: o dinheiro só chega ao vendedor depois de receber a encomenda.", en: "In a conversation, tap “🚫 Block” to stop receiving messages from that person and “🚩 Report” to alert the administration. In the Shop, use Protected payment when available: the money only reaches the seller after you receive the order.", zh: "在对话中，点击“🚫 屏蔽”即可不再接收此人的消息，点击“🚩 举报”可通知管理员。在商店中，如有保障付款请使用：您收到订单后，款项才会交给卖家。", fr: "Dans une conversation, touchez « 🚫 Bloquer » pour ne plus recevoir de messages de cette personne et « 🚩 Signaler » pour alerter l'administration. Dans la Boutique, utilisez le Paiement protégé quand il est disponible : l'argent n'arrive au vendeur qu'après réception de la commande." },
  // --- inspection
  "sv.in_my_store": { pt: "A minha loja", en: "My shop", zh: "我的店铺", fr: "Ma boutique" },
  "sv.in_title": { pt: "Selo «Inspecionado»", en: "“Inspected” badge", zh: "“已实地核查”标志", fr: "Badge «Inspecté»" },
  "sv.in_cancel_q": { pt: "Cancelar o pedido de inspeção?", en: "Cancel the inspection request?", zh: "取消核查申请？", fr: "Annuler la demande d'inspection ?" },
  "sv.in_intro": { pt: "Os clientes confiam mais em quem tem o selo. O selo vale um ano; depois pode pedir nova visita.", en: "Clients trust those with the badge more. The badge is valid for one year; after that you can request a new visit.", zh: "客户更信任拥有此标志的商家。标志有效期一年，之后可申请再次上门核查。", fr: "Les clients font davantage confiance à ceux qui ont le badge. Le badge est valable un an ; ensuite, vous pouvez demander une nouvelle visite." },
  "sv.in_diff": { pt: "Diferente do ✔ (documento verificado): aqui alguém da administração vai mesmo ao local.", en: "Different from ✔ (document verified): here someone from the administration actually visits the place.", zh: "与 ✔（证件已验证）不同：这里管理员会实地上门核查。", fr: "Différent de ✔ (document vérifié) : ici, quelqu'un de l'administration visite réellement le lieu." },
  "sv.in_fee": { pt: "Taxa da marcação: {pro} para profissionais e {biz} para lojas, empresas e fábricas.", en: "Booking fee: {pro} for professionals and {biz} for shops, businesses and factories.", zh: "预约费用：专业人士 {pro}，店铺、企业和工厂 {biz}。", fr: "Frais de réservation : {pro} pour les professionnels et {biz} pour les boutiques, entreprises et usines." },
  "sv.in_first": { pt: "Primeiro crie um", en: "First create a", zh: "请先创建", fr: "Créez d'abord un" },
