  "sv.in_request_again": { pt: "Pedir nova inspeção", en: "Request a new inspection", zh: "申请再次核查", fr: "Demander une nouvelle inspection" },
  "sv.in_request": { pt: "Pedir inspeção", en: "Request inspection", zh: "申请核查", fr: "Demander une inspection" },
  "sv.in_created": { pt: "Pedido criado. Agora pague a taxa e envie o comprovativo: depois a administração liga para marcar a visita.", en: "Request created. Now pay the fee and send the receipt: then the administration will call to book the visit.", zh: "申请已创建。请支付费用并上传凭证，随后管理员会致电预约上门时间。", fr: "Demande créée. Payez maintenant les frais et envoyez le justificatif : l'administration appellera ensuite pour fixer la visite." },
  "sv.in_address": { pt: "Morada e ponto de referência do local", en: "Address and landmark of the place", zh: "地点地址和参照地标", fr: "Adresse et point de repère du lieu" },
  "sv.in_address_ph": { pt: "Ex.: Bairro São João, rua da escola, portão verde", en: "E.g.: São João neighbourhood, school street, green gate", zh: "例如：São João 街区，学校那条街，绿色大门", fr: "Ex. : quartier São João, rue de l'école, portail vert" },
  "sv.in_phone": { pt: "Telefone para combinar a visita", en: "Phone to arrange the visit", zh: "预约上门的联系电话", fr: "Téléphone pour convenir de la visite" },
