  "sv.in_pay_sent": { pt: "Pagamento enviado. Quando a administração confirmar, liga para marcar a visita.", en: "Payment sent. Once the administration confirms it, they'll call to book the visit.", zh: "付款已提交。管理员确认后会致电预约上门时间。", fr: "Paiement envoyé. Une fois confirmé par l'administration, elle appellera pour fixer la visite." },
  "sv.in_pay_step": { pt: "Pague {amount} ao Huambo Online", en: "Pay {amount} to Huambo Online", zh: "向 Huambo Online 支付 {amount}", fr: "Payez {amount} à Huambo Online" },
