  "sv.ve_see_all_kinds": { pt: "Ver hotéis, restaurantes e armazéns", en: "See hotels, restaurants and warehouses", zh: "查看酒店、餐厅和仓库", fr: "Voir les hôtels, restaurants et entrepôts" },
  "sv.ve_proof_sent": { pt: "Comprovativo enviado. O estabelecimento vai confirmar o pagamento.", en: "Receipt sent. The venue will confirm the payment.", zh: "凭证已提交，商家将确认付款。", fr: "Justificatif envoyé. L'établissement va confirmer le paiement." },
  "sv.ve_held": { pt: "guardado", en: "held", zh: "保留至", fr: "maintenue" },
  "sv.ve_submitted_hint": { pt: "O estabelecimento está a confirmar o pagamento na conta dele. Ao chegar, lá verificam o QR e o comprovativo.", en: "The venue is confirming the payment in its account. When you arrive, they'll check the QR and the receipt.", zh: "商家正在核实其账户中的付款。到店时会核验二维码和凭证。", fr: "L'établissement confirme le paiement sur son compte. À votre arrivée, ils vérifieront le QR et le justificatif." },
  "sv.ve_pay_on_arrival": { pt: "Pague no estabelecimento, ao chegar.", en: "Pay at the venue when you arrive.", zh: "到店时在商家处付款。", fr: "Payez à l'établissement à votre arrivée." },
  "sv.ve_pay_step": { pt: "Pague {total} ao estabelecimento", en: "Pay {total} to the venue", zh: "向商家支付 {total}", fr: "Payez {total} à l'établissement" },
  "sv.ve_pay_warn": { pt: "Pague só para a conta do estabelecimento mostrada aqui. Nunca pague a quem lhe ligar a pedir outra conta.", en: "Only pay into the venue account shown here. Never pay anyone who calls you asking for another account.", zh: "只向此处显示的商家账户付款。切勿向打电话要求您转到其他账户的人付款。", fr: "Payez uniquement sur le compte de l'établissement affiché ici. Ne payez jamais quelqu'un qui vous appelle en demandant un autre compte." },
  "sv.ve_registered": { pt: "Registado! A administração vai confirmar antes de aparecer ao público.", en: "Registered! The administration will confirm it before it appears to the public.", zh: "登记成功！管理员确认后将对公众显示。", fr: "Inscrit ! L'administration va le confirmer avant qu'il n'apparaisse au public." },
  "sv.ve_edit_warn": { pt: "Se mudar a conta para pagamentos, o estabelecimento volta a ficar à espera de aprovação da administração (para evitar burlas).", en: "If you change the payment account, the venue goes back to awaiting administration approval (to prevent scams).", zh: "如果您更改收款账户，场所将重新等待管理员批准（以防诈骗）。", fr: "Si vous changez le compte de paiement, l'établissement repasse en attente d'approbation par l'administration (pour éviter les arnaques)." },
  "sv.ve_register_note": { pt: "A administração confirma o estabelecimento antes de aparecer ao público (para evitar estabelecimentos falsos). O nome, a morada, as fotografias e as avaliações vêm da sua empresa.", en: "The administration confirms the venue before it appears to the public (to prevent fake venues). The name, address, photos and reviews come from your business.", zh: "场所经管理员确认后才会对公众显示（以防虚假场所）。名称、地址、照片和评价来自您的企业。", fr: "L'administration confirme l'établissement avant qu'il n'apparaisse au public (pour éviter les faux établissements). Le nom, l'adresse, les photos et les évaluations viennent de votre entreprise." },
