  "sv.ve_my_venue_intro": { pt: "Hotel, hospedaria, restaurante ou armazém? Mostre o que tem e receba reservas e encomendas.", en: "Hotel, guesthouse, restaurant or warehouse? Show what you have and receive bookings and orders.", zh: "酒店、旅馆、餐厅或仓库？展示您的商品服务，接收预订和订单。", fr: "Hôtel, pension, restaurant ou entrepôt ? Montrez ce que vous avez et recevez réservations et commandes." },
  "sv.ve_my_venues": { pt: "Os meus estabelecimentos", en: "My venues", zh: "我的场所", fr: "Mes établissements" },
  "sv.ve_my_venues_intro": { pt: "Registar é grátis. Em cada pedido concluído, o cliente paga mais 5% e o estabelecimento dá 5% do seu preço: entrega os 10% ao Huambo Online.", en: "Registering is free. On each completed order, the client pays 5% extra and the venue gives 5% of its price: it passes the 10% on to Huambo Online.", zh: "登记免费。每完成一笔订单，客户多付 5%，商家让出其价格的 5%：共 10% 交给 Huambo Online。", fr: "L'inscription est gratuite. Pour chaque commande conclue, le client paie 5 % de plus et l'établissement cède 5 % de son prix : il reverse les 10 % à Huambo Online." },
  "sv.ve_none_registered": { pt: "Ainda não registou nenhum estabelecimento.", en: "You haven't registered any venue yet.", zh: "您还没有登记任何场所。", fr: "Vous n'avez encore inscrit aucun établissement." },
  "sv.ve_first_business": { pt: "Primeiro registe a sua empresa (nome, morada, telefone, fotografias). O estabelecimento fica ligado a ela, com o portfólio e as avaliações.", en: "First register your business (name, address, phone, photos). The venue is linked to it, with the portfolio and reviews.", zh: "请先登记您的企业（名称、地址、电话、照片）。场所将与之关联，并共享作品集和评价。", fr: "Inscrivez d'abord votre entreprise (nom, adresse, téléphone, photos). L'établissement y est lié, avec le portfolio et les évaluations." },
  "sv.ve_register_business": { pt: "Registar a minha empresa", en: "Register my business", zh: "登记我的企业", fr: "Enregistrer mon commerce" },
