  "sv.ve_cancelled_refund": { pt: "Pedido cancelado. Se o cliente já pagou, devolva o dinheiro.", en: "Order cancelled. If the client has already paid, refund the money.", zh: "订单已取消。如客户已付款，请退还款项。", fr: "Commande annulée. Si le client a déjà payé, remboursez-le." },
  "sv.ve_pending_add": { pt: "À espera de aprovação da administração. Entretanto, junte já os {items} com fotografias.", en: "Awaiting administration approval. Meanwhile, add your {items} with photos.", zh: "等待管理员批准。在此期间，请先添加带照片的{items}。", fr: "En attente d'approbation par l'administration. En attendant, ajoutez vos {items} avec des photos." },
  "sv.ve_suspended_hidden": { pt: "Suspenso: não aparece ao público nem recebe pedidos.", en: "Suspended: not visible to the public and not receiving orders.", zh: "已暂停：不对公众显示，也不接收订单。", fr: "Suspendu : non visible par le public et ne reçoit pas de commandes." },
