  "sv.ve_confirm_entry": { pt: "Confirmar entrada / entrega", en: "Confirm check-in / delivery", zh: "确认入场／交付", fr: "Confirmer l'arrivée / la remise" },
  "sv.ve_confirm_entry_hint": { pt: "Leia o QR do cliente com a câmara do telemóvel (abre a página que confirma se é verdadeiro) ou escreva aqui o código.", en: "Scan the client's QR with your phone camera (it opens the page that confirms whether it's genuine) or type the code here.", zh: "用手机相机扫描客户的二维码（会打开确认真伪的页面），或在此输入代码。", fr: "Scannez le QR du client avec la caméra du téléphone (cela ouvre la page qui confirme s'il est authentique) ou tapez le code ici." },
  "sv.ve_order_code": { pt: "Código do pedido", en: "Order code", zh: "订单代码", fr: "Code de la commande" },
