/** Perguntas frequentes (HELP_FAQ do core), pela pergunta em português. */
export const SV_HELP_FAQ: Record<"en" | "zh" | "fr", Record<string, { q: string; a: string }>> = {
  en: {
    "Como publico um anúncio?": { q: "How do I post a listing?", a: "Tap “Sell” or “Post listing”, choose the type and purpose, say how you want to sell (fixed price, negotiable, offers, auction or trade), add photos and publish." },
    "O que é «Preço fixo», «Negociável» e «Aberto a propostas»?": { q: "What are “Fixed price”, “Negotiable” and “Open to offers”?", a: "Fixed price: whoever wants it buys at the stated price (“I want to buy”). Negotiable: the buyer can make a lower offer. Open to offers: the price is just a reference and buyers say how much they'll pay." },
    "Como funcionam as trocas?": { q: "How do trades work?", a: "Choose “Trade only” or tick “I also accept trades” and say what you accept. Anyone interested proposes an item (and can add money). See them all in “Trades”." },
    "Como faço uma proposta?": { q: "How do I make an offer?", a: "On the listing, tap “Make an offer” and enter the amount and/or what you offer in exchange. The seller accepts or refuses and gets a notification; follow it in “My offers”." },
    "Como retiro uma proposta?": { q: "How do I withdraw an offer?", a: "In “My offers”, tap “Withdraw offer”. This is only possible while the seller hasn't replied; once accepted, agree with them by message." },
    "Como funcionam os leilões?": { q: "How do auctions work?", a: "Like on eBay: enter the MAXIMUM you're willing to pay. Huambo Online bids for you only as much as needed to stay ahead, up to that maximum, which nobody sees. If someone else offers more than your maximum, you get a notice and can raise it. In a tie, whoever bid first wins. The winner pays the final price, which is often lower than their maximum. Some auctions have “Buy now”: you can buy straight away at that price until someone bids. Follow everything in “My bids”; you get a notice when less than 1 hour is left." },
    "Como cancelo um lance num leilão?": { q: "How do I cancel a bid in an auction?", a: "On the auction listing, open “See bids” and tap “Withdraw my bid”, choosing the reason. You can do it if there are more than 12 hours left, or if the bid was placed less than 1 hour ago. At most 3 times in 30 days. The seller can also cancel a person's bids, explaining why." },
    "O que é o número do anúncio (ex.: A-1001)?": { q: "What is the listing number (e.g. A-1001)?", a: "Each listing (A-…), product (P-…) and order (E-…) has a short number shown on its page. Use it to talk to the seller or the administration, or type it in the search to open the item directly." },
    "Como mostro os meus trabalhos (portfólio)?": { q: "How do I show my work (portfolio)?", a: "Professionals: in “Your account” → “Professional profile” → “Portfolio”, tap “Add work”, give it a title and add up to 8 photos. Businesses: in “My businesses” → “Logo and portfolio”. The work appears on your public page, in “Completed work”, and you can change the order." },
    "Quanto custa ter perfil de profissional ou de empresa?": { q: "How much does a professional or business profile cost?", a: "The first month is free. After that, professionals pay 2,000 Kz per month and businesses 5,000 Kz per month. Pay in “Your account” → “My plan”, with the reference or receipt of the transfer or Multicaixa Express. You get notices 7 days and 1 day before it ends. Without payment, the profile stops being shown to clients until you pay." },
    "Quanto custa vender na Loja e nos anúncios?": { q: "How much does it cost to sell in the Shop and in listings?", a: "Shop: the first month is free, then 5,000 Kz per month (if the products belong to a business, the business's monthly fee is enough). Listings: posting is free; when you sell or rent out goods (vehicles, machinery…), you pay a 5% commission on the amount within 7 days, in “Your account” → “Commissions”. When marking “Sold” or “Rented” you enter the amount and see the commission straight away; for a rental request, the commission is on the total accepted amount. Renting out property (houses, apartments, land…) is free with no commissions." },
    "Como ponho o meu anúncio em destaque?": { q: "How do I feature my listing?", a: "In “My listings”, on the published listing, tap “⭐ Feature”. Pay the stated amount (500 Kz for 7 days) by transfer or Multicaixa Express and type the reference or attach the receipt. When the administration confirms, the listing appears at the top of the lists with the “⭐ Featured” badge. You can extend it before it ends." },
    "Como sigo um profissional, uma empresa ou uma loja?": { q: "How do I follow a professional, a business or a shop?", a: "On the page of the professional, business or seller, tap “➕ Follow”. You get a notice when they post a new listing, product or work (at most one notice per hour from each). See who you follow in “Your account” → “Following”; to unfollow, tap “✔ Following”." },
    "Como vendo produtos do campo (milho, batata, gado…)?": { q: "How do I sell farm produce (maize, potatoes, livestock…)?", a: "In “Sell”, choose the type “Item” or “Other” and turn on “🌾 Farm produce”. State the type (cereals, tubers, livestock…), the selling unit (kg, 50 kg bag, tonne, head…), the quantity and, if you haven't harvested yet, the “available from” date. The price is shown per unit (e.g. 12,000 Kz / 50 kg bag) and the listing goes into the “🌾 Agriculture and farming” section." },
    "Como peço um serviço a um profissional?": { q: "How do I request a service from a professional?", a: "Open the professional's or business's page and use “Request service”. When the service is finished, confirm and review it — the review is marked “Service confirmed”." },
    "Como avalio um vendedor ou comprador?": { q: "How do I review a seller or buyer?", a: "After a completed order, or when the listing is marked as sold to the right person, it appears in “Reviews” for you to rate." },
    "Como fico com o selo «Verificado»?": { q: "How do I get the “Verified” badge?", a: "In “Your account”, open “Verify profile” and send a photo of your ID card (or the business licence/tax number). The document stays private; the administration replies by notification." },
    "O que é o «Pagamento protegido»?": { q: "What is “Protected payment”?", a: "For Shop purchases, you can pay Huambo Online instead of paying the seller. We hold the money and the seller only receives it after you confirm you received the order. If there's a problem, ask for a refund in “Orders”: the money stays frozen until it's resolved. If you neither confirm nor complain a few days after delivery, the payment goes to the seller." },
    "Vendo na Loja: como recebo o dinheiro do pagamento protegido?": { q: "I sell in the Shop: how do I receive protected payment money?", a: "Wait for the “Payment received” notice before shipping. After delivering, mark the order as “Delivered”. When the client confirms (or the period passes without a complaint), the money goes to “Your account” → “My balance”. Enter your IBAN or Multicaixa Express number and tap “Request withdrawal”." },
    "Como partilho um anúncio no WhatsApp?": { q: "How do I share a listing on WhatsApp?", a: "Open the listing or product and tap “📲 Share on WhatsApp”. The message includes the title, price, listing number (e.g. A-1023) and the link, and WhatsApp shows the photo. Choose the contact or group." },
    "Os compradores podem ver o meu WhatsApp?": { q: "Can buyers see my WhatsApp?", a: "To protect your privacy, your number is not shown to buyers: they contact you through Huambo Online Messages. If you save your WhatsApp in “Your account” → “WhatsApp”, only the Huambo Online team can see it." },
    "Como funciona o «Convide um amigo»?": { q: "How does “Invite a friend” work?", a: "In “Account” → “Invite friends” you have your code and your link. Anyone who creates an account with your invitation (within the first 14 days) is linked to you. When that person pays their first monthly fee (professional, business or shop), you get 1 free month on your monthly fee. If you don't have a monthly fee yet, the reward is saved." },
    "O que é um agente no terreno?": { q: "What is a field agent?", a: "A person from the market (for example, Kapango) who helps sellers post listings on Huambo Online. The listing always stays in the seller's account; when posting, the seller enters the agent's code (e.g. AG1001). When that listing is sold, the agent earns a percentage of the sale amount, which the administration confirms and which goes into the agent's balance. To become an agent, open “Account” → “Become an agent”." },
    "E se o artigo não corresponder ao anúncio?": { q: "What if the item doesn't match the listing?", a: "All listings have a conformity guarantee: whoever posts declares that the description is true and complete, including defects. If the item you bought or rented has a hidden defect or is different, open the listing and tap “The item doesn't match the listing” (up to 7 days after the deal). You can ask for an exchange, return and refund, or a refund. If the owner refuses or doesn't reply within 3 days, the administration decides. For Shop purchases, use “Returns and refunds” on the order." },
    "Como evito burlas?": { q: "How do I avoid scams?", a: "Meet in a busy public place (see “Safe meeting points” in “Safety”), see the item and pay on delivery, or use Protected payment in the Shop. Never pay in advance or give out codes you receive by SMS or your PIN. In messages, Huambo Online warns you when someone asks for advance payment or codes. If you're suspicious, use “Block” and “Report”." },
    "Como peço uma devolução ou reembolso?": { q: "How do I ask for a return or refund?", a: "In “Orders”, choose the order and tap “Ask for a return or refund” (up to 14 days after delivery). Explain the problem and attach photos. If the seller refuses or doesn't reply, you can call the administration. See “Returns and refunds”." },
    "Como gasto menos dados (saldo)?": { q: "How do I use less data (airtime)?", a: "Turn on “📉 Data saver” at the top of the Site, on the APP home page or in “Your account”. Photos in lists stop loading (an icon appears) and, in listings, they only load when you tap “See the photos”. Videos only load when you tap ▶. On the Site, “Automatic” turns on by itself when the phone is in data-saving mode." },
    "Posso usar sem internet?": { q: "Can I use it without internet?", a: "You can see the home page, your last search and the last listings you opened. To post, send messages or offers you need a connection." },
    "Como pago por transferência ou Multicaixa Express?": { q: "How do I pay by bank transfer or Multicaixa Express?", a: "Use the payment details shown on the screen (IBAN or Multicaixa Express number) and pay the exact amount. Then, on the same screen, send a clear photo or screenshot of the whole receipt showing the amount, date, destination account and operation number. The team checks it against the bank statement, confirms it and you get a notification." },
    "O meu pagamento falhou ou foi recusado. O que faço?": { q: "My payment failed or was rejected. What should I do?", a: "If the money didn't leave your account, try again. If it did and the payment was rejected, see the reason in the notification: usually the receipt can't be read, the amount is wrong or it was paid to another account. Send the right receipt again, or talk to the team on WhatsApp or through Messages, giving the operation number. Never send your PIN or codes you receive by SMS." },
    "O que faz o assistente de IA?": { q: "What does the AI assistant do?", a: "It helps you post and find things faster: «📷 Fill in from photo» suggests the title, category and details of a listing from a photo; «✨ Improve with AI» rewrites the text; «✨ Smart search» understands requests like «diesel car up to 5 million»; and the Help assistant answers questions. Always review what the AI suggests. There is a daily usage limit." },
    "Como apago a minha conta?": { q: "How do I delete my account?", a: "In “Your account”, at the bottom of the page, type ELIMINAR and confirm. See the details in “How to delete my account”." },
  },
  zh: {
    "Como publico um anúncio?": { q: "如何发布广告？", a: "点击“出售”或“发布广告”，选择类型和用途，说明出售方式（固定价、可议价、接受报价、拍卖或交换），添加照片后发布。" },
    "O que é «Preço fixo», «Negociável» e «Aberto a propostas»?": { q: "什么是“固定价”“可议价”和“接受报价”？", a: "固定价：想要的人按标价购买（“我要购买”）。可议价：买家可以出更低的价格。接受报价：价格仅供参考，由买家报出愿意支付的金额。" },
    "Como funcionam as trocas?": { q: "交换如何进行？", a: "选择“仅交换”或勾选“也接受交换”，并说明您接受的物品。感兴趣的人会提出一件物品（也可以加钱）。在“交换”中查看全部。" },
    "Como faço uma proposta?": { q: "如何报价？", a: "在广告中点击“报价”，填写金额和／或用于交换的物品。卖家接受或拒绝，并会收到通知；您可以在“我的报价”中跟进。" },
    "Como retiro uma proposta?": { q: "如何撤回报价？", a: "在“我的报价”中点击“撤回报价”。只有在卖家尚未回复时才能撤回；被接受后，请通过消息与卖家协商。" },
    "Como funcionam os leilões?": { q: "拍卖如何进行？", a: "和 eBay 一样：填写您愿意支付的最高价。Huambo Online 会替您按需出价以保持领先，直至该最高价，而这个最高价别人看不到。如果有人出价超过您的最高价，您会收到通知并可以加价。出价相同时，先出价者获胜。获胜者支付最终价格，通常低于其最高价。部分拍卖设有“立即购买”：在有人出价之前，您可以直接按该价格购买。在“我的出价”中跟进全部情况；距结束不到 1 小时时会通知您。" },
    "Como cancelo um lance num leilão?": { q: "如何取消拍卖中的出价？", a: "在拍卖广告中打开“查看出价”，点击“撤回我的出价”并选择原因。距结束超过 12 小时，或出价不到 1 小时时可以撤回。30 天内最多 3 次。卖家也可以在说明原因后取消某人的出价。" },
    "O que é o número do anúncio (ex.: A-1001)?": { q: "广告编号（例如 A-1001）是什么？", a: "每条广告（A-…）、商品（P-…）和订单（E-…）都有一个短编号，显示在页面上。可以用它与卖家或管理员沟通，或在搜索中输入编号直接打开该项。" },
    "Como mostro os meus trabalhos (portfólio)?": { q: "如何展示我的作品（作品集）？", a: "专业人士：在“您的账户”→“专业资料”→“作品集”中点击“添加作品”，填写标题并添加最多 8 张照片。企业：在“我的企业”→“标志和作品集”中操作。作品会显示在您的公开页面“已完成作品”中，并可调整顺序。" },
    "Quanto custa ter perfil de profissional ou de empresa?": { q: "专业人士或企业资料收费多少？", a: "第一个月免费。之后专业人士每月 2 000 Kz，企业每月 5 000 Kz。请在“您的账户”→“我的套餐”中付款，并提供转账或 Multicaixa Express 的参考号或凭证。到期前 7 天和 1 天会收到提醒。未付款期间，资料不会向客户显示，直至付款。" },
    "Quanto custa vender na Loja e nos anúncios?": { q: "在商店和广告中销售收费多少？", a: "商店：第一个月免费，之后每月 5 000 Kz（如果商品属于某个企业，只需支付企业月费）。广告：发布免费；出售或出租物品（车辆、机械等）时，需在 7 天内在“您的账户”→“佣金”中支付金额的 5% 佣金。标记“已售出”或“已出租”时填写金额即可看到佣金；租赁请求的佣金按接受的总金额计算。房产（房屋、公寓、土地等）出租免费，无任何佣金。" },
    "Como ponho o meu anúncio em destaque?": { q: "如何推荐我的广告？", a: "在“我的广告”中，找到已发布的广告并点击“⭐ 推荐”。通过转账或 Multicaixa Express 支付所示金额（7 天 500 Kz），填写参考号或附上凭证。管理员确认后，广告会显示在列表顶部并带有“⭐ 推荐”标志。您可以在结束前续期。" },
    "Como sigo um profissional, uma empresa ou uma loja?": { q: "如何关注专业人士、企业或店铺？", a: "在专业人士、企业或卖家的页面点击“➕ 关注”。对方发布新广告、商品或作品时您会收到通知（每个对象每小时最多一条）。在“您的账户”→“关注中”查看您关注的对象；要取消关注，请点击“✔ 关注中”。" },
    "Como vendo produtos do campo (milho, batata, gado…)?": { q: "如何出售农产品（玉米、土豆、牲畜…）？", a: "在“出售”中选择类型“物品”或“其他”，并开启“🌾 农产品”。填写种类（谷物、块茎、牲畜…）、销售单位（公斤、50 公斤袋、吨、头…）、数量，如尚未收获，请填写“可供应日期”。价格按单位显示（例如 12 000 Kz／50 公斤袋），广告会进入“🌾 农业”栏目。" },
    "Como peço um serviço a um profissional?": { q: "如何向专业人士请求服务？", a: "打开专业人士或企业的页面，使用“请求服务”。服务完成后请确认并评价——该评价会标记为“服务已确认”。" },
    "Como avalio um vendedor ou comprador?": { q: "如何评价卖家或买家？", a: "订单完成后，或广告被标记为已售给对应的人后，该交易会出现在“评价”中供您评价。" },
    "Como fico com o selo «Verificado»?": { q: "如何获得“已验证”标志？", a: "在“您的账户”中打开“验证资料”，上传身份证照片（或企业的营业执照／税号）。证件保持私密；管理员会通过通知答复。" },
    "O que é o «Pagamento protegido»?": { q: "什么是“保障付款”？", a: "在商店购物时，您可以向 Huambo Online 付款，而不是直接付给卖家。我们代为保管资金，您确认收货后卖家才会收到款项。如有问题，可在“订单”中申请退款：款项会被冻结直至问题解决。如果收货后几天内您既未确认也未投诉，款项将转给卖家。" },
    "Vendo na Loja: como recebo o dinheiro do pagamento protegido?": { q: "我在商店销售：如何收到保障付款的款项？", a: "收到“已收到付款”通知后再发货。交付后，将订单标记为“已交付”。客户确认（或期限内无投诉）后，款项进入“您的账户”→“我的余额”。填写您的 IBAN 或 Multicaixa Express 号码，然后点击“申请提现”。" },
    "Como partilho um anúncio no WhatsApp?": { q: "如何在 WhatsApp 上分享广告？", a: "打开广告或商品，点击“📲 分享到 WhatsApp”。消息包含标题、价格、广告编号（例如 A-1023）和链接，WhatsApp 中会显示照片。选择联系人或群组即可。" },
    "Os compradores podem ver o meu WhatsApp?": { q: "买家能看到我的 WhatsApp 吗？", a: "为保护您的隐私，您的号码不会向买家显示：他们通过 Huambo Online 站内消息与您联系。如果您在“您的账户”→“WhatsApp”中保存号码，只有 Huambo Online 团队能看到。" },
    "Como funciona o «Convide um amigo»?": { q: "“邀请朋友”如何运作？", a: "在“账户”→“邀请朋友”中有您的邀请码和链接。通过您的邀请注册账户的人（在注册后 14 天内）会与您关联。当对方支付首月月费（专业人士、企业或店铺）时，您的月费可获得 1 个月免费。如果您还没有月费，奖励会被保留。" },
    "O que é um agente no terreno?": { q: "什么是地推代理？", a: "来自市场（例如 Kapango）的人，帮助卖家在 Huambo Online 上发布广告。广告始终在卖家本人的账户中；发布时，卖家填写代理代码（例如 AG1001）。该广告售出后，代理可获得成交金额的一定比例，经管理员确认后计入代理余额。要成为代理，请打开“账户”→“成为代理”。" },
    "E se o artigo não corresponder ao anúncio?": { q: "如果物品与广告不符怎么办？", a: "所有广告都有如实描述保证：发布者声明描述真实完整，包括缺陷。如果您购买或租用的物品有隐藏缺陷或与描述不同，请打开该广告并点击“物品与广告不符”（交易后 7 天内）。您可以要求换货、退货退款或退款。如物主拒绝或 3 天内未回复，由管理员裁决。商店购物请在订单中使用“退货和退款”。" },
    "Como evito burlas?": { q: "如何避免诈骗？", a: "在人多的公共场所见面（参见“安全”中的“安全见面地点”），查看物品后当面付款，或在商店中使用保障付款。切勿预付款，也不要透露短信收到的验证码或 PIN。在消息中，如果有人要求预付款或索要验证码，Huambo Online 会提醒您。如有怀疑，请使用“屏蔽”和“举报”。" },
    "Como peço uma devolução ou reembolso?": { q: "如何申请退货或退款？", a: "在“订单”中选择订单，点击“申请退货或退款”（收货后 14 天内）。说明问题并附上照片。如果卖家拒绝或未回复，您可以请管理员介入。参见“退货和退款”。" },
    "Como gasto menos dados (saldo)?": { q: "如何节省流量（话费）？", a: "在网站顶部、APP 首页或“您的账户”中开启“📉 节省流量”。列表中的照片不再加载（显示为图标），广告中的照片只有在点击“查看照片”时才加载。视频只有在点击 ▶ 时才加载。在网站上，“自动”模式会在手机开启省流量时自动启用。" },
    "Posso usar sem internet?": { q: "没有网络可以使用吗？", a: "可以查看首页、最近一次搜索和最近打开的广告。发布、发送消息或报价需要网络连接。" },
    "Como pago por transferência ou Multicaixa Express?": { q: "如何通过银行转账或 Multicaixa Express 付款？", a: "使用屏幕上显示的付款信息（IBAN 或 Multicaixa Express 号码）支付准确金额。然后在同一页面上传完整收据的清晰照片或截图，需显示金额、日期、收款账户和交易编号。团队会核对银行流水并确认，您会收到通知。" },
    "O meu pagamento falhou ou foi recusado. O que faço?": { q: "我的付款失败或被拒绝了，怎么办？", a: "如果钱没有从您的账户扣除，请重试。如果已扣款但付款被拒绝，请查看通知中的原因：通常是收据无法读取、金额错误或付到了其他账户。请重新上传正确的收据，或通过 WhatsApp 或站内消息联系团队并提供交易编号。切勿发送 PIN 或短信验证码。" },
    "O que faz o assistente de IA?": { q: "AI 助手能做什么？", a: "它能帮您更快地发布和查找：「📷 用照片填写」根据照片建议信息的标题、类别和详情；「✨ 用 AI 优化」重写文字；「✨ 智能搜索」能理解「500万以内的柴油车」之类的请求；帮助助手会回答您的问题。请始终检查 AI 的建议。每天有使用次数限制。" },
    "Como apago a minha conta?": { q: "如何删除我的账户？", a: "在“您的账户”页面底部输入 ELIMINAR 并确认。详情请参见“如何删除我的账户”。" },
  },
  fr: {
    "Como publico um anúncio?": { q: "Comment publier une annonce ?", a: "Touchez « Vendre » ou « Publier une annonce », choisissez le type et l'objectif, dites comment vous voulez vendre (prix fixe, négociable, offres, enchère ou échange), ajoutez des photos et publiez." },
    "O que é «Preço fixo», «Negociável» e «Aberto a propostas»?": { q: "Que signifient « Prix fixe », « Négociable » et « Ouvert aux offres » ?", a: "Prix fixe : qui le veut l'achète au prix indiqué (« Je veux acheter »). Négociable : l'acheteur peut proposer un prix plus bas. Ouvert aux offres : le prix n'est qu'une référence et les acheteurs disent combien ils paieraient." },
    "Como funcionam as trocas?": { q: "Comment fonctionnent les échanges ?", a: "Choisissez « Échange uniquement » ou cochez « J'accepte aussi les échanges » et dites ce que vous acceptez. Les intéressés proposent un article (et peuvent ajouter de l'argent). Voyez-les tous dans « Échanges »." },
    "Como faço uma proposta?": { q: "Comment faire une offre ?", a: "Sur l'annonce, touchez « Faire une offre » et indiquez le montant et/ou ce que vous proposez en échange. Le vendeur accepte ou refuse et reçoit une notification ; suivez-la dans « Mes offres »." },
    "Como retiro uma proposta?": { q: "Comment retirer une offre ?", a: "Dans « Mes offres », touchez « Retirer l'offre ». Ce n'est possible que tant que le vendeur n'a pas répondu ; une fois acceptée, arrangez-vous avec lui par message." },
    "Como funcionam os leilões?": { q: "Comment fonctionnent les enchères ?", a: "Comme sur eBay : indiquez le MAXIMUM que vous êtes prêt à payer. Huambo Online enchérit pour vous seulement ce qu'il faut pour rester en tête, jusqu'à ce maximum, que personne ne voit. Si quelqu'un propose plus que votre maximum, vous recevez un avis et pouvez l'augmenter. En cas d'égalité, celui qui a enchéri en premier gagne. Le gagnant paie le prix final, souvent inférieur à son maximum. Certaines enchères ont « Acheter maintenant » : vous pouvez acheter tout de suite à ce prix tant que personne n'a enchéri. Suivez tout dans « Mes enchères » ; vous recevez un avis quand il reste moins d'1 heure." },
    "Como cancelo um lance num leilão?": { q: "Comment annuler une enchère ?", a: "Sur l'annonce de l'enchère, ouvrez « Voir les enchères » et touchez « Retirer mon enchère », en choisissant le motif. C'est possible s'il reste plus de 12 heures, ou si l'enchère a été placée il y a moins d'1 heure. Au maximum 3 fois en 30 jours. Le vendeur peut aussi annuler les enchères d'une personne, en expliquant pourquoi." },
    "O que é o número do anúncio (ex.: A-1001)?": { q: "Qu'est-ce que le numéro de l'annonce (ex. : A-1001) ?", a: "Chaque annonce (A-…), produit (P-…) et commande (E-…) a un numéro court affiché sur sa page. Utilisez-le pour parler au vendeur ou à l'administration, ou tapez-le dans la recherche pour ouvrir directement l'élément." },
    "Como mostro os meus trabalhos (portfólio)?": { q: "Comment montrer mes réalisations (portfolio) ?", a: "Professionnels : dans « Votre compte » → « Profil professionnel » → « Portfolio », touchez « Ajouter une réalisation », donnez un titre et ajoutez jusqu'à 8 photos. Entreprises : dans « Mes entreprises » → « Logo et portfolio ». Les réalisations apparaissent sur votre page publique, dans « Réalisations », et vous pouvez changer l'ordre." },
    "Quanto custa ter perfil de profissional ou de empresa?": { q: "Combien coûte un profil de professionnel ou d'entreprise ?", a: "Le premier mois est gratuit. Ensuite, les professionnels paient 2 000 Kz par mois et les entreprises 5 000 Kz par mois. Payez dans « Votre compte » → « Mon forfait », avec la référence ou le justificatif du virement ou de Multicaixa Express. Vous recevez des avis 7 jours et 1 jour avant la fin. Sans paiement, le profil n'est plus montré aux clients jusqu'au paiement." },
    "Quanto custa vender na Loja e nos anúncios?": { q: "Combien coûte la vente dans la Boutique et dans les annonces ?", a: "Boutique : le premier mois est gratuit, puis 5 000 Kz par mois (si les produits appartiennent à une entreprise, la mensualité de l'entreprise suffit). Annonces : publier est gratuit ; quand vous vendez ou louez des biens (véhicules, machines…), vous payez une commission de 5 % du montant dans les 7 jours, dans « Votre compte » → « Commissions ». En marquant « Vendu » ou « Loué », vous indiquez le montant et voyez tout de suite la commission ; pour une demande de location, la commission porte sur le montant total accepté. La location de biens immobiliers (maisons, appartements, terrains…) est gratuite, sans commission." },
    "Como ponho o meu anúncio em destaque?": { q: "Comment mettre mon annonce à la une ?", a: "Dans « Mes annonces », sur l'annonce publiée, touchez « ⭐ Mettre à la une ». Payez le montant indiqué (500 Kz pour 7 jours) par virement ou Multicaixa Express et tapez la référence ou joignez le justificatif. Quand l'administration confirme, l'annonce apparaît en haut des listes avec le badge « ⭐ À la une ». Vous pouvez prolonger avant la fin." },
    "Como sigo um profissional, uma empresa ou uma loja?": { q: "Comment suivre un professionnel, une entreprise ou une boutique ?", a: "Sur la page du professionnel, de l'entreprise ou du vendeur, touchez « ➕ Suivre ». Vous recevez un avis quand il publie une nouvelle annonce, un produit ou une réalisation (au maximum un avis par heure pour chacun). Voyez qui vous suivez dans « Votre compte » → « Abonnements » ; pour ne plus suivre, touchez « ✔ Abonné »." },
    "Como vendo produtos do campo (milho, batata, gado…)?": { q: "Comment vendre des produits agricoles (maïs, pommes de terre, bétail…) ?", a: "Dans « Vendre », choisissez le type « Article » ou « Autre » et activez « 🌾 Produit agricole ». Indiquez le type (céréales, tubercules, bétail…), l'unité de vente (kg, sac de 50 kg, tonne, tête…), la quantité et, si vous n'avez pas encore récolté, la date « disponible à partir du ». Le prix est affiché par unité (ex. : 12 000 Kz / sac de 50 kg) et l'annonce va dans la section « 🌾 Agriculture et élevage »." },
    "Como peço um serviço a um profissional?": { q: "Comment demander un service à un professionnel ?", a: "Ouvrez la page du professionnel ou de l'entreprise et utilisez « Demander un service ». Une fois le service terminé, confirmez-le et évaluez-le — l'évaluation est marquée « Service confirmé »." },
    "Como avalio um vendedor ou comprador?": { q: "Comment évaluer un vendeur ou un acheteur ?", a: "Après une commande conclue, ou quand l'annonce est marquée comme vendue à la bonne personne, elle apparaît dans « Évaluations » pour que vous l'évaluiez." },
    "Como fico com o selo «Verificado»?": { q: "Comment obtenir le badge « Vérifié » ?", a: "Dans « Votre compte », ouvrez « Vérifier le profil » et envoyez une photo de votre carte d'identité (ou de la licence commerciale/du numéro fiscal de l'entreprise). Le document reste privé ; l'administration répond par notification." },
    "O que é o «Pagamento protegido»?": { q: "Qu'est-ce que le « Paiement protégé » ?", a: "Pour les achats dans la Boutique, vous pouvez payer Huambo Online au lieu de payer le vendeur. Nous retenons l'argent et le vendeur ne le reçoit qu'après que vous avez confirmé avoir reçu la commande. En cas de problème, demandez un remboursement dans « Commandes » : l'argent reste gelé jusqu'à la résolution. Si vous ne confirmez pas et ne vous plaignez pas quelques jours après la livraison, le paiement va au vendeur." },
    "Vendo na Loja: como recebo o dinheiro do pagamento protegido?": { q: "Je vends dans la Boutique : comment recevoir l'argent du paiement protégé ?", a: "Attendez l'avis « Paiement reçu » avant d'expédier. Après la livraison, marquez la commande comme « Livrée ». Quand le client confirme (ou que le délai passe sans réclamation), l'argent va dans « Votre compte » → « Mon solde ». Indiquez votre IBAN ou numéro Multicaixa Express et touchez « Demander un retrait »." },
    "Como partilho um anúncio no WhatsApp?": { q: "Comment partager une annonce sur WhatsApp ?", a: "Ouvrez l'annonce ou le produit et touchez « 📲 Partager sur WhatsApp ». Le message contient le titre, le prix, le numéro de l'annonce (ex. : A-1023) et le lien, et WhatsApp affiche la photo. Choisissez le contact ou le groupe." },
    "Os compradores podem ver o meu WhatsApp?": { q: "Les acheteurs peuvent-ils voir mon WhatsApp ?", a: "Pour protéger votre vie privée, votre numéro n'est pas montré aux acheteurs : ils vous contactent via les Messages de Huambo Online. Si vous enregistrez votre WhatsApp dans « Votre compte » → « WhatsApp », seule l'équipe de Huambo Online peut le voir." },
    "Como funciona o «Convide um amigo»?": { q: "Comment fonctionne « Inviter un ami » ?", a: "Dans « Compte » → « Inviter des amis », vous avez votre code et votre lien. Quiconque crée un compte avec votre invitation (dans les 14 premiers jours) vous est lié. Quand cette personne paie sa première mensualité (professionnel, entreprise ou boutique), vous gagnez 1 mois gratuit sur votre mensualité. Si vous n'avez pas encore de mensualité, la récompense est mise de côté." },
    "O que é um agente no terreno?": { q: "Qu'est-ce qu'un agent de terrain ?", a: "Une personne du marché (par exemple, Kapango) qui aide les vendeurs à publier des annonces sur Huambo Online. L'annonce reste toujours dans le compte du vendeur ; en publiant, le vendeur indique le code de l'agent (ex. : AG1001). Quand cette annonce est vendue, l'agent gagne un pourcentage du montant de la vente, que l'administration confirme et qui va dans le solde de l'agent. Pour devenir agent, ouvrez « Compte » → « Devenir agent »." },
    "E se o artigo não corresponder ao anúncio?": { q: "Et si l'article ne correspond pas à l'annonce ?", a: "Toutes les annonces ont une garantie de conformité : celui qui publie déclare que la description est vraie et complète, défauts compris. Si l'article que vous avez acheté ou loué a un défaut caché ou est différent, ouvrez l'annonce et touchez « L'article ne correspond pas à l'annonce » (jusqu'à 7 jours après l'affaire). Vous pouvez demander un échange, un retour avec remboursement ou un remboursement. Si le propriétaire refuse ou ne répond pas dans les 3 jours, l'administration tranche. Pour les achats dans la Boutique, utilisez « Retours et remboursements » sur la commande." },
    "Como evito burlas?": { q: "Comment éviter les arnaques ?", a: "Donnez rendez-vous dans un lieu public fréquenté (voir « Points de rencontre sûrs » dans « Sécurité »), voyez l'article et payez à la remise, ou utilisez le Paiement protégé dans la Boutique. Ne payez jamais d'avance et ne donnez jamais les codes reçus par SMS ni votre PIN. Dans les messages, Huambo Online vous avertit quand quelqu'un demande un paiement anticipé ou des codes. En cas de doute, utilisez « Bloquer » et « Signaler »." },
    "Como peço uma devolução ou reembolso?": { q: "Comment demander un retour ou un remboursement ?", a: "Dans « Commandes », choisissez la commande et touchez « Demander un retour ou un remboursement » (jusqu'à 14 jours après la livraison). Expliquez le problème et joignez des photos. Si le vendeur refuse ou ne répond pas, vous pouvez faire appel à l'administration. Voir « Retours et remboursements »." },
    "Como gasto menos dados (saldo)?": { q: "Comment consommer moins de données (crédit) ?", a: "Activez « 📉 Économie de données » en haut du Site, sur l'accueil de l'APP ou dans « Votre compte ». Les photos des listes ne se chargent plus (une icône apparaît) et, dans les annonces, elles ne se chargent que lorsque vous touchez « Voir les photos ». Les vidéos ne se chargent que lorsque vous touchez ▶. Sur le Site, « Automatique » s'active tout seul quand le téléphone est en mode économie de données." },
    "Posso usar sem internet?": { q: "Puis-je l'utiliser sans internet ?", a: "Vous pouvez voir l'accueil, votre dernière recherche et les dernières annonces ouvertes. Pour publier, envoyer des messages ou des offres, il faut une connexion." },
    "Como pago por transferência ou Multicaixa Express?": { q: "Comment payer par virement bancaire ou Multicaixa Express ?", a: "Utilisez les coordonnées de paiement affichées à l'écran (IBAN ou numéro Multicaixa Express) et payez le montant exact. Ensuite, sur le même écran, envoyez une photo nette ou une capture du justificatif complet montrant le montant, la date, le compte de destination et le numéro d'opération. L'équipe le compare au relevé bancaire, le confirme et vous recevez une notification." },
    "O meu pagamento falhou ou foi recusado. O que faço?": { q: "Mon paiement a échoué ou a été refusé. Que faire ?", a: "Si l'argent n'est pas sorti de votre compte, réessayez. S'il est sorti et que le paiement a été refusé, voyez le motif dans la notification : en général, le justificatif est illisible, le montant est incorrect ou le paiement a été fait sur un autre compte. Renvoyez le bon justificatif, ou parlez à l'équipe sur WhatsApp ou via Messages, en indiquant le numéro d'opération. N'envoyez jamais votre PIN ni les codes reçus par SMS." },
    "O que faz o assistente de IA?": { q: "Que fait l'assistant IA ?", a: "Il vous aide à publier et à trouver plus vite : « 📷 Remplir à partir de la photo » suggère le titre, la catégorie et les détails d'une annonce à partir d'une photo ; « ✨ Améliorer avec l'IA » réécrit le texte ; « ✨ Recherche intelligente » comprend des demandes comme « voiture diesel jusqu'à 5 millions » ; et l'assistant d'aide répond aux questions. Vérifiez toujours ce que l'IA suggère. Il y a une limite d'utilisation quotidienne." },
    "Como apago a minha conta?": { q: "Comment supprimer mon compte ?", a: "Dans « Votre compte », en bas de la page, tapez ELIMINAR et confirmez. Voir les détails dans « Comment supprimer mon compte »." },
  },
};

